sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float intensity;
uniform float blockHeight;
uniform float seed;

float hash(float2 p) {
    return fract(sin(dot(p, float2(12.9898, 78.233 + seed))) * 43758.5453);
}

float noise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    float a = hash(i);
    float b = hash(i + float2(1.0, 0.0));
    float c = hash(i + float2(0.0, 1.0));
    float d = hash(i + float2(1.0, 1.0));
    float2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

half4 main(float2 coord) {
    float t = floor(time * 4.0) / 4.0;
    float block = floor(coord.y / blockHeight);
    float glitchNoise = noise(float2(block, t * 100.0));
    float offset = (glitchNoise - 0.5) * intensity * 20.0;
    float rNoise = noise(float2(coord.x * 0.1 + t * 50.0, block * 10.0));
    float gNoise = noise(float2(coord.x * 0.1 + t * 50.0 + 100.0, block * 10.0));
    float bNoise = noise(float2(coord.x * 0.1 + t * 50.0 + 200.0, block * 10.0));
    float rOffset = (rNoise - 0.5) * intensity * 10.0;
    float gOffset = (gNoise - 0.5) * intensity * 10.0;
    float bOffset = (bNoise - 0.5) * intensity * 10.0;
    float2 rCoord = coord + float2(offset + rOffset, 0.0);
    float2 gCoord = coord + float2(offset + gOffset, 0.0);
    float2 bCoord = coord + float2(offset + bOffset, 0.0);
    rCoord = clamp(rCoord, float2(0.0), size - 1.0);
    gCoord = clamp(gCoord, float2(0.0), size - 1.0);
    bCoord = clamp(bCoord, float2(0.0), size - 1.0);
    half4 rCol = image.eval(rCoord);
    half4 gCol = image.eval(gCoord);
    half4 bCol = image.eval(bCoord);
    half alpha = max(max(rCol.a, gCol.a), bCol.a);
    if (alpha < 0.001) {
        return half4(0.0);
    }
    float r = unpremul(rCol).r;
    float g = unpremul(gCol).g;
    float b = unpremul(bCol).b;
    return half4(r * alpha, g * alpha, b * alpha, alpha);
}
